"""Standalone replay viewer; frames are generated by the real Python simulator."""
import json
from pathlib import Path
from .evaluation import rollout
from .policy import faulty_policy, tracking_policy


def build_demo(path):
    policies = {"Random actions": None, "Broken: reversed controls": faulty_policy("reversed_controls"),
                "Repaired: ball tracker": tracking_policy()}
    data = {name: [rollout(p, s, record=True) for s in range(8)] for name,p in policies.items()}
    template = Path(__file__).with_name("viewer.html").read_text(encoding="utf-8")
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(template.replace("__REPLAYS__", json.dumps(data)), encoding="utf-8")
